def utf8_kodla(cp):
    if cp < 0x80:
        return [cp]
    if cp < 0x800:
        return [0xC0 | (cp >> 6), 0x80 | (cp & 0x3F)]
    if cp < 0x10000:
        return [0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)]
    return [0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F),
            0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)]

for cp in (0x41, 0x11E, 0x20AC):
    b = utf8_kodla(cp)
    dogru = list(chr(cp).encode("utf-8"))
    print(cp, len(b), " ".join("%02X" % x for x in b), b == dogru)

def cp(s):
    return "+".join("%04X" % ord(c) for c in s)

