KURAL = {
    "tr": lambda n: "other",
    "en": lambda n: "one" if n == 1 else "other",
}
SABLON = {
    "tr": {"other": "{n} yeni ileti"},
    "en": {"one": "{n} new message", "other": "{n} new messages"},
}

def bicimle(dil, n):
    return SABLON[dil][KURAL[dil](n)].format(n=n)

for dil in ("tr", "en"):
    print(dil, "|", " / ".join(bicimle(dil, n) for n in (0, 1, 5)))

def tr_sayi(x):
    tam, _, kesir = ("%.2f" % x).partition(".")
    gruplu = ""
    while len(tam) > 3:
        gruplu = "." + tam[-3:] + gruplu
        tam = tam[:-3]
    return tam + gruplu + "," + kesir

print(tr_sayi(1234567.5), tr_sayi(999.4))

def kodla(alanlar):
    out = bytearray()
    for etiket in sorted(alanlar):
        ham = str(alanlar[etiket]).encode("utf-8")
        out += bytes([etiket, len(ham)]) + ham
    return bytes(out)

def coz(veri):
    i, alanlar = 0, {}
    while i < len(veri):
        etiket, uzunluk = veri[i], veri[i + 1]
        alanlar[etiket] = veri[i + 2:i + 2 + uzunluk].decode("utf-8")
        i += 2 + uzunluk
    return alanlar

yeni = {1: "KAYIT-7", 2: "199900", 3: "TRY", 9: "yeni-alan"}
paket = kodla(yeni)
print(len(paket), sorted(coz(paket)))

BILINEN = {1, 2, 3}
eski_gorunum = {e: d for e, d in coz(paket).items() if e in BILINEN}
print(sorted(eski_gorunum.items()))
print(len(kodla(eski_gorunum)), kodla(eski_gorunum) == paket)
print(coz(kodla(coz(paket))) == coz(paket))
